from __future__ import annotations

import math
from datetime import datetime, timezone
from typing import Annotated, Literal, Union
from uuid import uuid4

from pydantic import BaseModel, ConfigDict, Field, computed_field, field_validator, model_validator

SCHEMA_VERSION = "0.2.0"


def new_id(prefix: str) -> str:
    return f"{prefix}_{uuid4().hex[:16]}"


class CBIMModel(BaseModel):
    model_config = ConfigDict(extra="forbid", populate_by_name=True, serialize_by_alias=True)


class Point2D(CBIMModel):
    x: float
    y: float


class Point3D(CBIMModel):
    x: float
    y: float
    z: float = 0.0


class SourceRef(CBIMModel):
    source_id: str
    entity_id: str
    source_type: str = "cad"
    layer: str | None = None
    metadata: dict[str, str | int | float | bool | None] = Field(default_factory=dict)


class Site(CBIMModel):
    id: str = Field(default_factory=lambda: new_id("site"))
    name: str
    latitude: float | None = Field(default=None, ge=-90, le=90)
    longitude: float | None = Field(default=None, ge=-180, le=180)
    elevation: float = 0.0
    properties: dict[str, str | int | float | bool | None] = Field(default_factory=dict)


class Building(CBIMModel):
    id: str = Field(default_factory=lambda: new_id("building"))
    name: str
    site_id: str | None = None
    properties: dict[str, str | int | float | bool | None] = Field(default_factory=dict)


class Storey(CBIMModel):
    id: str = Field(default_factory=lambda: new_id("storey"))
    name: str
    building_id: str | None = None
    elevation: float
    height: float = Field(gt=0)
    properties: dict[str, str | int | float | bool | None] = Field(default_factory=dict)


class Material(CBIMModel):
    id: str = Field(default_factory=lambda: new_id("material"))
    name: str
    category: str | None = None
    manufacturer: str | None = None
    product_code: str | None = None
    properties: dict[str, str | int | float | bool | None] = Field(default_factory=dict)


class System(CBIMModel):
    id: str = Field(default_factory=lambda: new_id("system"))
    name: str
    discipline: Literal["architecture", "structure", "plumbing", "fire", "hvac", "electrical", "other"] = "other"
    classification: str | None = None
    properties: dict[str, str | int | float | bool | None] = Field(default_factory=dict)


ReviewState = Literal["auto", "confirmed", "rejected", "edited"]


class ElementBase(CBIMModel):
    id: str
    type: str
    name: str | None = None
    storey_id: str | None = None
    confidence: float = Field(default=1.0, ge=0.0, le=1.0)
    review_state: ReviewState = "auto"
    source_refs: list[SourceRef] = Field(default_factory=list)
    material_ids: list[str] = Field(default_factory=list)
    properties: dict[str, str | int | float | bool | None] = Field(default_factory=dict)


class Wall(ElementBase):
    id: str = Field(default_factory=lambda: new_id("wall"))
    type: Literal["wall"] = "wall"
    start: Point3D
    end: Point3D
    thickness: float = Field(gt=0)
    height: float = Field(gt=0)

    @computed_field
    @property
    def length(self) -> float:
        return math.dist((self.start.x, self.start.y, self.start.z), (self.end.x, self.end.y, self.end.z))


class Column(ElementBase):
    id: str = Field(default_factory=lambda: new_id("column"))
    type: Literal["column"] = "column"
    center: Point3D
    width: float = Field(gt=0)
    depth: float = Field(gt=0)
    height: float = Field(gt=0)
    rotation_deg: float = 0.0


class Beam(ElementBase):
    id: str = Field(default_factory=lambda: new_id("beam"))
    type: Literal["beam"] = "beam"
    start: Point3D
    end: Point3D
    width: float = Field(gt=0)
    height: float = Field(gt=0)


class Slab(ElementBase):
    id: str = Field(default_factory=lambda: new_id("slab"))
    type: Literal["slab"] = "slab"
    boundary: list[Point3D] = Field(min_length=3)
    thickness: float = Field(gt=0)


class Door(ElementBase):
    id: str = Field(default_factory=lambda: new_id("door"))
    type: Literal["door"] = "door"
    position: Point3D
    width: float = Field(gt=0)
    height: float = Field(gt=0)
    host_id: str | None = None
    rotation_deg: float = 0.0


class Window(ElementBase):
    id: str = Field(default_factory=lambda: new_id("window"))
    type: Literal["window"] = "window"
    position: Point3D
    width: float = Field(gt=0)
    height: float = Field(gt=0)
    sill_height: float = Field(default=1.0, ge=0)
    host_id: str | None = None
    rotation_deg: float = 0.0


class Space(ElementBase):
    id: str = Field(default_factory=lambda: new_id("space"))
    type: Literal["space"] = "space"
    boundary: list[Point3D] = Field(min_length=3)
    height: float = Field(gt=0)


class Pipe(ElementBase):
    id: str = Field(default_factory=lambda: new_id("pipe"))
    type: Literal["pipe"] = "pipe"
    path: list[Point3D] = Field(min_length=2)
    diameter: float = Field(gt=0)
    system_id: str | None = None
    slope: float | None = None


class Fitting(ElementBase):
    id: str = Field(default_factory=lambda: new_id("fitting"))
    type: Literal["fitting"] = "fitting"
    position: Point3D
    fitting_type: Literal["elbow", "tee", "reducer", "coupling", "cross", "cap", "other"] = "other"
    nominal_diameter: float | None = Field(default=None, gt=0)
    system_id: str | None = None


class Equipment(ElementBase):
    id: str = Field(default_factory=lambda: new_id("equipment"))
    type: Literal["equipment"] = "equipment"
    position: Point3D
    equipment_type: str
    system_id: str | None = None
    rotation_deg: float = 0.0


class Opening(ElementBase):
    id: str = Field(default_factory=lambda: new_id("opening"))
    type: Literal["opening"] = "opening"
    position: Point3D
    width: float = Field(gt=0)
    height: float = Field(gt=0)
    depth: float | None = Field(default=None, gt=0)
    host_id: str | None = None


CBIMElement = Annotated[
    Union[Wall, Column, Beam, Slab, Door, Window, Space, Pipe, Fitting, Equipment, Opening],
    Field(discriminator="type"),
]


RelationType = Literal[
    "host", "contains", "connects", "belongs_to_system", "belongs_to_storey", "source", "parent_child"
]


class Relation(CBIMModel):
    id: str = Field(default_factory=lambda: new_id("relation"))
    type: RelationType
    from_id: str
    to_id: str
    metadata: dict[str, str | int | float | bool | None] = Field(default_factory=dict)


class CBIMProject(CBIMModel):
    id: str = Field(default_factory=lambda: new_id("project"))
    schema_name: Literal["CBIM"] = Field(default="CBIM", alias="schema", serialization_alias="schema")
    schema_version: str = SCHEMA_VERSION
    name: str
    created_at: datetime = Field(default_factory=lambda: datetime.now(timezone.utc))
    units: Literal["m"] = "m"
    coordinate_reference: str = "local"
    sites: list[Site] = Field(default_factory=list)
    buildings: list[Building] = Field(default_factory=list)
    storeys: list[Storey] = Field(default_factory=list)
    materials: list[Material] = Field(default_factory=list)
    systems: list[System] = Field(default_factory=list)
    elements: list[CBIMElement] = Field(default_factory=list)
    relations: list[Relation] = Field(default_factory=list)
    metadata: dict[str, str | int | float | bool | None] = Field(default_factory=dict)

    @field_validator("schema_version")
    @classmethod
    def supported_schema_version(cls, value: str) -> str:
        if value != SCHEMA_VERSION:
            raise ValueError(f"Unsupported CBIM schema version: {value}; expected {SCHEMA_VERSION}")
        return value

    @model_validator(mode="after")
    def validate_graph(self) -> "CBIMProject":
        collections = [self.sites, self.buildings, self.storeys, self.materials, self.systems, self.elements]
        ids = [item.id for collection in collections for item in collection]
        if len(ids) != len(set(ids)):
            raise ValueError("CBIM IDs must be unique within a project")
        known = {self.id, *ids}
        for rel in self.relations:
            if rel.from_id not in known or rel.to_id not in known:
                raise ValueError(f"Relation {rel.id} references an unknown CBIM ID")
        for building in self.buildings:
            if building.site_id and building.site_id not in {s.id for s in self.sites}:
                raise ValueError(f"Building {building.id} references unknown site {building.site_id}")
        for storey in self.storeys:
            if storey.building_id and storey.building_id not in {b.id for b in self.buildings}:
                raise ValueError(f"Storey {storey.id} references unknown building {storey.building_id}")
        storey_ids = {s.id for s in self.storeys}
        material_ids = {m.id for m in self.materials}
        system_ids = {s.id for s in self.systems}
        element_ids = {e.id for e in self.elements}
        for element in self.elements:
            if element.storey_id and element.storey_id not in storey_ids:
                raise ValueError(f"Element {element.id} references unknown storey {element.storey_id}")
            unknown_materials = set(element.material_ids) - material_ids
            if unknown_materials:
                raise ValueError(f"Element {element.id} references unknown materials: {sorted(unknown_materials)}")
            system_id = getattr(element, "system_id", None)
            if system_id and system_id not in system_ids:
                raise ValueError(f"Element {element.id} references unknown system {system_id}")
            host_id = getattr(element, "host_id", None)
            if host_id and host_id not in element_ids:
                raise ValueError(f"Element {element.id} references unknown host {host_id}")
        return self

    def element_counts(self) -> dict[str, int]:
        counts: dict[str, int] = {}
        for element in self.elements:
            counts[element.type] = counts.get(element.type, 0) + 1
        return counts
